import{_ as a,o as t,c as s,a5 as r}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Transportes actuales y restricciones de plataforma","description":"","frontmatter":{"title":"Transportes actuales y restricciones de plataforma","docId":"developer.transports","translationKey":"developer.transports","locale":"es","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6696987a0db16b3b4d364c6136d0e552dbebd6fc68346e3ed031587a7b004468","translationRevision":"1d16d732eaf401a9004105ac650774e0b60757e2ac74241077e6a6a1e39841c4","order":200},"headers":[],"relativePath":"es/developer/transports.md","filePath":"es/developer/transports.md","lastUpdated":1794611623000}'),i={name:"es/developer/transports.md"};function o(n,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Transportes actuales y restricciones de plataforma <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;Transportes actuales y restricciones de plataforma {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Selecciona el transporte que existe en la compilación y plataforma de destino. Lee <a href="./control-api.html">Control API</a> y <a href="./collaboration.html">colaboración</a>. Un transporte lleva operaciones serializadas; no debe crear otro núcleo ni otorgar autoridad por sí mismo.</p><h2 id="choose-the-boundary" tabindex="-1">Elegir el límite <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;Elegir el límite {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recorrido</th><th>Implementación actual</th><th>Límite importante</th></tr></thead><tbody><tr><td>WebView de escritorio</td><td>IPC Wry y cliente compartido</td><td>Ventana e hilo pertenecen al escritorio</td></tr><tr><td>CLI local</td><td>Socket Unix o tubería Windows; host stdio explícito</td><td>Mismo directorio y propietario</td></tr><tr><td>Navegador local</td><td>Adaptador nativo y <code>browser-transport.ts</code></td><td>Host emparejado, no simulación ni servidor remoto público</td></tr><tr><td>Remoto directo</td><td>Gateway HTTPS/WSS y transportes SDK/navegador</td><td>TLS, negociación, permisos y características</td></tr><tr><td>Par nativo</td><td><code>tiktools-peer</code>, flujo iroh/QUIC cifrado</td><td>Identidad de par no equivale a autoridad RPC</td></tr><tr><td>WebRTC nativo</td><td><code>tiktools-rtc</code>, señalización firmada y canales de datos</td><td>Exige negociación, permisos y ruta comprobada</td></tr></tbody></table><p>La interfaz TypeScript está en <code>src/web/shared/api/control-transport.ts</code>. El transporte de pares no activa implícitamente relays públicos ni descubrimiento de terceros. WebRTC es nativo Rust (<code>webrtc</code> 0.21.1), sin depender de <code>RTCPeerConnection</code> del navegador en la interfaz del escritorio.</p><h2 id="inspect-the-selected-route" tabindex="-1">Inspeccionar la ruta seleccionada <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;Inspeccionar la ruta seleccionada {#inspect-the-selected-route}&quot;">​</a></h2><p>Descubre métodos y capacidades del host antes de emparejar o mostrar acciones del controlador:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-browser-transport</span></span></code></pre></div><p><code>tiktools-rtc/src/route.rs</code> observa el par ICE seleccionado para clasificar conexión directa o relay. El estado listo no demuestra una ruta directa. La señalización/relay Cloud es independiente de la autorización y debe conservar la comprobación de permisos nativos.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>IPC local y transporte de escritorio son rutas establecidas. Pares nativos, WebRTC y controlador tienen código y pruebas dirigidas, pero despliegue y aceptación entre equipos siguen experimentales. Los textos que afirman ausencia de pares/relay son históricos. Android admite IPC local; los perfiles remotos persistidos carecen de almacén de credenciales seleccionado y no hay addons/WebView de escritorio.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Una desconexión puede dejar operaciones aceptadas inciertas. Reconectar exige invalidar proyecciones privadas, negociar identidad y reanudar o recargar flujos acotados. No debilites certificados ni vuelvas silenciosamente al propietario local tras un fallo remoto. La <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-rtc/src" target="_blank" rel="noreferrer">implementación RTC</a> y el grafo real sustituyen planes antiguos.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Peer usa ALPN <code>tiktools/collaboration/1</code>, timeout actual de 15 s y hasta cuatro relays configurados explícitamente. Peer/RTC limitan tramas a 1 MiB; RTC fragmenta en paquetes de hasta 16 KiB. Una trama excesiva falla validación, no produce RPC parcial. Diagnostica por separado configuración/identidad, señalización, timeout, tamaño y autorización. Relay Cloud no es servidor TURN de ICE; una lista vacía no habilita discovery público. Comprueba host/dispositivo y permiso confirmado vigente antes de probar ruta, y registra si ICE elige directo o relay. Transporte ready/cifrado no demuestra autoridad ni acceso por todo NAT. Prueba sesión cambiada/revocada y tramas excesivas con fixtures antes de aceptar dos PC reales.</p>`,16)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
